svg.script:

document.addEventListener("DOMContentLoaded", () => {
  const targetUrl = "index.html"; // single
  const iframe = document.getElementById("content-frame");

  fetch(targetUrl)
    .then(response => {
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      return response.text();
    })
    .then(htmlContent => {
      // Inject the fetched HTML into the iframe's srcdoc
      iframe.srcdoc = htmlContent;
    })
    .catch(error => {
      console.error("Failed to fetch URL:", error);
      iframe.srcdoc = `<p style="font-family: sans-serif; color: red;">Error loading content: ${error.message}</p>`;
    });
});
